#pragma once
#include "GB/World/Graph/ITerrainNode.h"

namespace GB
{
	// "height_input": brings a field into the graph from outside it. The name of the field is the node's Source (default "height"); the caller
	// supplies it in TgContext::Inputs. This is how a terrain that was generated by other means (the bare hills WorldGen carves its water into)
	// enters a graph that analyses it: the graph does not need to know how the ground was made.
	class HeightInputNode final : public ITerrainNode
	{
	public:
		TgNodeSchema Describe() const override;
		bool Evaluate(const TgNode& node, const TgContext& ctx, const std::vector<const TgField*>& inputs, TgField& out, std::string& error) const override;
	};
}
